// ============ CONFIG (tune these) ============
const FIRST_TOUCH_SLA_HOURS = 24;    // after deal closes, rep must reach out within this
const FOLLOWUP_GAP_HOURS    = 48;    // max silence between rep touches while payment is pending
const PAYMENT_ESCALATE_DAYS = 7;     // unpaid for this long -> escalate to manager
const TZ = 'Asia/Kolkata';
const LOCATION_ID = 'fn2vUNrBDZlI9mXJUFJv';
const AUTOMATED_SOURCES = ['workflow', 'campaign', 'bulk_actions', 'api', 'automation']; // not a human rep touch
const SYSTEM_TYPES = /ACTIVITY|NO_SHOW|APPOINTMENT/;                                     // not a real conversation

// ============ HELPERS ============
const now = new Date();
const hrs = (a, b) => (a - b) / 36e5;
const round = n => Math.round(n * 10) / 10;
const safe = (fn, fb = null) => { try { const v = fn(); return (v === undefined || v === null) ? fb : v; } catch (e) { return fb; } };
const clean = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const ist = d => d ? new Date(d).toLocaleString('en-IN', { timeZone: TZ, day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : null;
const byNewest = (a, b) => new Date(b.dateAdded) - new Date(a.dateAdded);

const allTasks = safe(() => $('Fetch HighLevel Contact Tasks').all().map(i => i.json), []);
const seen = new Set();
const results = [];

$input.all().forEach((item, idx) => {
  // ---- pull everything paired to this opportunity ----
  const opp = safe(() => $('Filter New Opportunities').itemMatching(idx).json, null)
           || safe(() => $('Filter New Opportunities').first().json, {});
  if (!opp.id || seen.has(opp.id)) return;          // dedupe (task node can output >1 item per opp)
  seen.add(opp.id);

  const hist     = safe(() => $('Fetch Conversation Messages').itemMatching(idx).json, {});
  const convo    = safe(() => $('Search Contact Conversations').itemMatching(idx).json.conversations[0], {});
  const charges  = safe(() => item.json.data, []);

  const closedAt = new Date(opp.lastStageChangeAt || opp.updatedAt || opp.createdAt);
  const hoursSinceClose = hrs(now, closedAt);

  // ---- PAYMENT (Stripe) ----
  const currency = (charges[0] && charges[0].currency) || 'usd';
  const netAmt = c => ((c.amount_captured || 0) - (c.amount_refunded || 0)) / 100;
  const okCharges = charges.filter(c => c.paid && c.status === 'succeeded');
  const paidSinceClose = okCharges
    .filter(c => new Date(c.created * 1000) >= closedAt)
    .reduce((s, c) => s + netAmt(c), 0);
  const expected = Number(opp.monetaryValue) || 0;
  const outstanding = Math.max(0, expected - paidSinceClose);
  const paymentStatus = outstanding === 0 ? 'PAID_IN_FULL' : (paidSinceClose > 0 ? 'PARTIAL' : 'UNPAID');
  const lastCharge = [...okCharges].sort((a, b) => b.created - a.created)[0];

  // ---- COMMUNICATION (GHL conversation) ----
  const msgs = safe(() => hist.messages.messages, []);
  const real = msgs.filter(m => m.type !== 28 && !SYSTEM_TYPES.test(String(m.messageType || '')));
  const isAuto = m => AUTOMATED_SOURCES.includes(String(m.source || '').toLowerCase());
  const repMsgs  = real.filter(m => m.direction === 'outbound' && !isAuto(m)).sort(byNewest);
  const autoMsgs = real.filter(m => m.direction === 'outbound' && isAuto(m)).sort(byNewest);
  const inbound  = real.filter(m => m.direction === 'inbound').sort(byNewest);
  const lastRep  = repMsgs[0] ? new Date(repMsgs[0].dateAdded) : null;
  const lastIn   = inbound[0] ? new Date(inbound[0].dateAdded) : null;
  const repTouchesSinceClose = repMsgs.filter(m => new Date(m.dateAdded) >= closedAt).length;
  const hoursSinceRepTouch = lastRep ? hrs(now, lastRep) : null;
  const hoursSinceCustomerMsg = lastIn ? hrs(now, lastIn) : null;
  const customerUnanswered = !!lastIn && (!lastRep || lastIn > lastRep);

  // ---- TASKS (GHL) ----
  const tasks = allTasks
    .filter(t => t && t.contactId && t.contactId === opp.contactId)
    .map(t => ({
      title: t.title,
      note: clean(t.body),
      due_at: t.dueDate,
      due_ist: ist(t.dueDate),
      completed: !!t.completed,
      overdue: !t.completed && !!t.dueDate && new Date(t.dueDate) < now,
      hours_until_due: t.dueDate ? round(hrs(new Date(t.dueDate), now)) : null
    }));
  const openTasks = tasks.filter(t => !t.completed);
  const overdueTasks = tasks.filter(t => t.overdue);

  // ---- DETERMINISTIC FLAGS (AI treats these as facts) ----
  const flags = [];
  if (paymentStatus === 'PAID_IN_FULL') {
    flags.push('PAID_IN_FULL');
  } else {
    if (paymentStatus === 'PARTIAL') flags.push('PARTIAL_PAYMENT');
    if (repTouchesSinceClose === 0) {
      flags.push(hoursSinceClose > FIRST_TOUCH_SLA_HOURS ? 'NO_FOLLOW_UP_SINCE_CLOSE' : 'WITHIN_FIRST_TOUCH_SLA');
    } else if (hoursSinceRepTouch !== null && hoursSinceRepTouch > FOLLOWUP_GAP_HOURS) {
      flags.push('STALE_FOLLOW_UP');
    }
    if (customerUnanswered) flags.push('CUSTOMER_REPLIED_UNANSWERED');
    if (openTasks.length === 0) flags.push('NO_OPEN_TASK');
    if (overdueTasks.length > 0) flags.push('TASK_OVERDUE');
    if (!opp.assignedTo) flags.push('NO_OWNER_ASSIGNED');
    if (hoursSinceClose / 24 > PAYMENT_ESCALATE_DAYS) flags.push('PAYMENT_OVERDUE_ESCALATE');
  }

  results.push({
    pairedItem: { item: idx },
    json: {
      context: {
        generated_at_ist: ist(now),
        thresholds: {
          first_touch_sla_hours: FIRST_TOUCH_SLA_HOURS,
          max_gap_between_rep_touches_hours: FOLLOWUP_GAP_HOURS,
          escalate_after_days_unpaid: PAYMENT_ESCALATE_DAYS
        },
        deal: {
          opportunity_id: opp.id,
          name: opp.name,
          value: expected,
          closed_at_ist: ist(closedAt),
          hours_since_close: round(hoursSinceClose),
          days_since_close: round(hoursSinceClose / 24),
          owner_assigned: !!opp.assignedTo,
          win_probability: opp.effectiveProbability,
          ghl_link: 'https://app.gohighlevel.com/v2/location/' + LOCATION_ID + '/contacts/detail/' + opp.contactId
        },
        contact: {
          id: opp.contactId,
          name: safe(() => opp.contact.name, convo.fullName || 'Unknown'),
          email: safe(() => opp.contact.email, convo.email || null)
        },
        payment: {
          status: paymentStatus,
          currency: currency,
          expected: expected,
          paid_since_close: paidSinceClose,
          outstanding: outstanding,
          successful_charges_all_time: okCharges.length,
          last_successful_charge: lastCharge
            ? { amount: netAmt(lastCharge), date_ist: ist(lastCharge.created * 1000), description: lastCharge.description }
            : null
        },
        communication: {
          rep_touches_since_close: repTouchesSinceClose,
          rep_touches_all_time: repMsgs.length,
          last_rep_touch_ist: ist(lastRep),
          hours_since_last_rep_touch: hoursSinceRepTouch === null ? null : round(hoursSinceRepTouch),
          automated_messages_sent: autoMsgs.length,
          last_customer_message_ist: ist(lastIn),
          hours_since_last_customer_message: hoursSinceCustomerMsg === null ? null : round(hoursSinceCustomerMsg),
          customer_reply_unanswered: customerUnanswered,
          last_conversation_event: convo.lastMessageType || null
        },
        tasks: {
          open_count: openTasks.length,
          overdue_count: overdueTasks.length,
          list: tasks
        },
        flags: flags
      }
    }
  });
});

return results;

// ===== CONFIG =====
const RENOTIFY_AFTER_DAYS = 0;       // 0 = never alert the same opportunity twice. e.g. 3 = remind again after 3 days
const ID_COLUMN = 'opportunity_id';  // column names in the "Notification Log" sheet
const TS_COLUMN = 'notified_at';

// 1) opportunity IDs already logged in the sheet
const now = Date.now();
const alreadyNotified = new Set();
for (const row of $input.all()) {
  const id = String(row.json[ID_COLUMN] ?? '').trim();
  if (!id) continue;                 // empty placeholder item when the sheet has no rows yet
  if (RENOTIFY_AFTER_DAYS > 0) {
    const t = new Date(row.json[TS_COLUMN]).getTime();
    if (!isNaN(t) && (now - t) / 864e5 >= RENOTIFY_AFTER_DAYS) continue;  // reminder is due -> treat as new
  }
  alreadyNotified.add(id);
}

// 2) keep only opportunities (from the "If" node) that are NOT in the sheet
const allOpps = $('Check Opportunity Value').all();
const fresh = allOpps.filter(o => !alreadyNotified.has(String(o.json.id)));
console.log(`Opportunities: ${allOpps.length} | already notified: ${allOpps.length - fresh.length} | new: ${fresh.length}`);

return fresh.map(o => ({ json: o.json }));
